{
  "name": "payroll-backend",
  "version": "1.0.0",
  "description": "Backend for Automated Payroll Processing System",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "cors": "^2.8.5",
    "express": "^4.19.2"
  }
}
// This is the entry point of the backend. Run this file to start the server.
const express = require('express');
const cors = require('cors');
const approvalRoutes = require('./src/routes/approvalRoutes');

const app = express();

app.use(cors()); // allows the frontend (different port) to call this backend
app.use(express.json()); // lets us read JSON sent in request bodies

// All payroll approval endpoints live under /api/payrolls
app.use('/api/payrolls', approvalRoutes);

const PORT = 5000;
app.listen(PORT, () => {
  console.log(`Backend server running on http://localhost:${PORT}`);
});
// This file holds our sample payroll data and the logic to change it.
// It's an in-memory array for now instead of a real database.
// Once someone runs "approve" or "reject", the array is updated
// directly (this data resets every time the server restarts).

let payrolls = [
  {
    id: 1,
    employeeName: 'Alice Tan',
    period: 'June 2026',
    grossPay: 3500,
    cpf: 700,
    sdl: 35,
    netPay: 2765,
    status: 'pending',
    comment: '',
  },
  {
    id: 2,
    employeeName: 'Ben Lim',
    period: 'June 2026',
    grossPay: 4200,
    cpf: 840,
    sdl: 42,
    netPay: 3318,
    status: 'pending',
    comment: '',
  },
  {
    id: 3,
    employeeName: 'Chen Wei',
    period: 'June 2026',
    grossPay: 3900,
    cpf: 780,
    sdl: 39,
    netPay: 3081,
    status: 'pending',
    comment: '',
  },
  {
    id: 4,
    employeeName: 'Divya Nair',
    period: 'June 2026',
    grossPay: 3100,
    cpf: 620,
    sdl: 31,
    netPay: 2449,
    status: 'approved',
    comment: '',
  },
];

// Returns every payroll record, so the manager can see all statuses
function getAllPayrolls() {
  return payrolls;
}

// Finds a payroll record by id and marks it as approved
function approvePayroll(id) {
  const payroll = payrolls.find((p) => p.id === Number(id));
  if (!payroll) return null;

  payroll.status = 'approved';
  payroll.comment = '';
  return payroll;
}

// Finds a payroll record by id, marks it rejected, and saves the manager's comment
function rejectPayroll(id, comment) {
  const payroll = payrolls.find((p) => p.id === Number(id));
  if (!payroll) return null;

  payroll.status = 'rejected';
  payroll.comment = comment && comment.trim() ? comment : 'No reason given';
  return payroll;
}

module.exports = {
  getAllPayrolls,
  approvePayroll,
  rejectPayroll,
};
// This file handles incoming requests: it reads what the request needs,
// calls the service to do the real work, then sends back a response.
const approvalService = require('../services/approvalService');

// GET /api/payrolls - send back the full list of payroll records
function listPayrolls(req, res) {
  const payrolls = approvalService.getAllPayrolls();
  res.json(payrolls);
}

// POST /api/payrolls/:id/approve - approve one payroll record
function approvePayroll(req, res) {
  const { id } = req.params;
  const updated = approvalService.approvePayroll(id);

  if (!updated) {
    return res.status(404).json({ message: 'Payroll record not found' });
  }

  res.json({
    message: `Payroll for ${updated.employeeName} was approved successfully.`,
    payroll: updated,
  });
}

// POST /api/payrolls/:id/reject - reject one payroll record with a comment
function rejectPayroll(req, res) {
  const { id } = req.params;
  const { comment } = req.body;
  const updated = approvalService.rejectPayroll(id, comment);

  if (!updated) {
    return res.status(404).json({ message: 'Payroll record not found' });
  }

  res.json({
    message: `Payroll for ${updated.employeeName} was rejected and sent back to accounting.`,
    payroll: updated,
  });
}

module.exports = {
  listPayrolls,
  approvePayroll,
  rejectPayroll,
};
// This file just maps URLs + HTTP methods to controller functions.
const express = require('express');
const router = express.Router();
const approvalController = require('../controllers/approvalController');

router.get('/', approvalController.listPayrolls);
router.post('/:id/approve', approvalController.approvePayroll);
router.post('/:id/reject', approvalController.rejectPayroll);

module.exports = router;
