// The top-level component. For now it just shows the payroll approval page.
import ApprovalPage from './pages/ApprovalPage.jsx';

function App() {
  return <ApprovalPage />;
}

export default App;
// UC-004: Review & Approve Payroll
// This page lets a manager see all payroll records, approve them,
// or reject them with a comment. The backend is a simple Express API.
import { useState, useEffect } from 'react';

const API_URL = 'http://localhost:5000/api/payrolls';

function ApprovalPage() {
  const [payrolls, setPayrolls] = useState([]);
  const [message, setMessage] = useState('');
  const [rejectingId, setRejectingId] = useState(null); // which row is showing the comment box
  const [comment, setComment] = useState('');

  // Load the payroll list once when the page first opens
  useEffect(() => {
    loadPayrolls();
  }, []);

  function loadPayrolls() {
    fetch(API_URL)
      .then((res) => res.json())
      .then((data) => setPayrolls(data));
  }

  function handleApprove(id) {
    fetch(`${API_URL}/${id}/approve`, { method: 'POST' })
      .then((res) => res.json())
      .then((data) => {
        setMessage(data.message);
        loadPayrolls();
      });
  }

  function handleRejectClick(id) {
    setRejectingId(id);
    setComment('');
  }

  function handleRejectSubmit(id) {
    fetch(`${API_URL}/${id}/reject`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ comment }),
    })
      .then((res) => res.json())
      .then((data) => {
        setMessage(data.message);
        setRejectingId(null);
        loadPayrolls();
      });
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'Arial, sans-serif' }}>
      <h1>Payroll Approval</h1>
      <p>Manager view: approve or reject payroll records below.</p>

      {message && (
        <div
          style={{
            background: '#d4edda',
            color: '#155724',
            padding: '1rem',
            marginBottom: '1rem',
            borderRadius: '4px',
          }}
        >
          {message}
        </div>
      )}

      <table border="1" cellPadding="8" style={{ borderCollapse: 'collapse', width: '100%' }}>
        <thead>
          <tr>
            <th>Employee</th>
            <th>Period</th>
            <th>Gross Pay</th>
            <th>CPF</th>
            <th>SDL</th>
            <th>Net Pay</th>
            <th>Status</th>
            <th>Comment</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {payrolls.map((p) => (
            <tr key={p.id}>
              <td>{p.employeeName}</td>
              <td>{p.period}</td>
              <td>${p.grossPay}</td>
              <td>${p.cpf}</td>
              <td>${p.sdl}</td>
              <td>${p.netPay}</td>
              <td>{p.status}</td>
              <td>{p.comment}</td>
              <td>
                {p.status === 'pending' && (
                  <>
                    <button onClick={() => handleApprove(p.id)}>Approve</button>{' '}
                    <button onClick={() => handleRejectClick(p.id)}>Reject</button>
                  </>
                )}

                {rejectingId === p.id && (
                  <div style={{ marginTop: '0.5rem' }}>
                    <input
                      type="text"
                      placeholder="Reason for rejection"
                      value={comment}
                      onChange={(e) => setComment(e.target.value)}
                    />
                    <button onClick={() => handleRejectSubmit(p.id)}>Submit</button>
                  </div>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default ApprovalPage;
// This is where the React app is mounted into the HTML page.
import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.jsx';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
